"""Get the path of the given module. It first checks if the system is frozen. If it is, it checks if it is frozen by PyInstaller or others and then returns the path accordingly. If the system is not frozen, it returns the path of the module. If the file is None, it raises RuntimeError(f"Can't find path from module `{module}.").

:param module: ModuleType. The module for which the path is to be found.
:return: str. The path of the given module.
"""
if getattr(sys, "frozen", False):
    if hasattr(sys, "_MEIPASS"):
        # PyInstaller
        return getattr(sys, "_MEIPASS")
    if hasattr(sys, "_MEIPASS2"):
        # PyInstaller 3.5+
        return getattr(sys, "_MEIPASS2")
    if hasattr(sys, "executable"):
        # Cython
        return os.path.dirname(sys.executable)
    # Unknown packager
    raise RuntimeError("Can't find path from frozen module.")
return module.__file__

"""This function generates a random string of upper and lowercase letters. It can generate a random string of a specific length between the minimum and maximum length. It can also add a prefix and suffix to the random string.

:param self: Provider. An instance of the Provider class.
:param min_chars: Optional integer. The minimum length of the random part. Defaults to None.
:param max_chars: Integer. The maximum length of the random part. Defaults to 20.
:param prefix: String. An optional prefix to prepend to the random string. Defaults to an empty string.
:param suffix: String. An optional suffix to append to the random string. Defaults to an empty string.
:return: String. Random of random length between min and max characters.
"""
if min_chars is None:
    min_chars = 0
if min_chars > max_chars:
    raise ValueError("min_chars must be less than or equal to max_chars")
if min_chars < 0:
    raise ValueError("min_chars must be greater than or equal to 0")
if max_chars < 0:
    raise ValueError("max_chars must be greater than or equal to 0")

return prefix + "".join(
    random.choice(string.ascii_letters) for _ in range(random.randint(min_chars, max_chars))
) + suffix

"""Sort the given models based on their dependencies. It uses a depth-first search to sort the models based on their dependencies and returns the sorted list of models.

:param models: List. A list of model instances to be sorted.
:return: List. The sorted list of model instances based on their dependencies.
"""
# Create a dictionary of lists for the models.
model_deps = {}
for model in models:
    model_deps[model] = model._meta.model_dependencies

# Create a dictionary of lists for the reverse dependencies.
reverse_deps = {}
for model in models:
    reverse_deps[model] = []
for model in models:
    for dep in model._meta.model_dependencies:
        reverse_deps[dep].append(model)

# Perform a depth-first search on the model dependencies.
sorted_models = []
while len(model_deps) > 0:
    # Find all models that have no dependencies.
    ready = [model for model in model_deps if len(model_deps[model]) == 0]
    # If there are no models with no dependencies, check if there is a cycle.
    if len(ready) == 0:
        for model in model_deps:
            if model in reverse_deps[model]:
                raise RuntimeError("Cycle detected in model dependencies.")
        # If there is no cycle, check if there are missing dependencies.
        else:
            deps_not_met = []
            for model in model_deps:
                for dep in model_deps[model]:
                    if dep not in model_deps:
                        deps_not_met.append(model)
                        break
            raise RuntimeError("Unmet dependencies: %s" % deps_not_met)
    # Add the models with no dependencies to the sorted list.
    sorted_models.extend(ready)
    # Remove the models with no dependencies from the dependency dictionaries.
    for model in ready:
        del model_deps[model]
    for model in ready:
        for dep in reverse_deps[model]:
            if model in model_deps[dep]:
                model_deps[dep].remove(model)
    # Remove the models with no dependencies from the reverse dependency dictionaries.
    for model in ready:
        del reverse_deps[model]
        for dep in reverse_deps:
            if model in reverse_deps[dep]:
                reverse_deps[dep].remove(model)

return sorted_models

