    return 62

if match["regex"] == "re":
    return 1

if match["regex"] == "re4":
    return 4

if match["regex"] == "re62":
    return 62

if match["regex"] == "re128":
    return 128

if match["regex"] == "re256":
    return 256

if match["regex"] == "re512":
