"""Add a rule to a SecurityGroup instance. Note that this method only changes the local version of the instance. No information is sent to EC2.

:param self: SecurityGroup. An instance of the SecurityGroup class.
:param ip_protocol: String. The IP protocol for the rule.
:param from_port: Integer. The starting port range for the rule.
:param to_port: Integer. The ending port range for the rule.
:param src_group_name: String. The name of the source security group.
:param src_group_owner_id: String. The ID of the owner of the source security group.
:param cidr_ip: String. The CIDR IP range for the rule.
:param src_group_group_id: String. The ID of the source security group.
:param dry_run: Bool. Whether to perform a dry run. Defaults to False.
:return: No return values.
"""
if src_group_name:
    src_group_name = src_group_name.strip()
if src_group_group_id:
    src_group_group_id = src_group_group_id.strip()
if src_group_owner_id:
    src_group_owner_id = src_group_owner_id.strip()
if cidr_ip:
    cidr_ip = cidr_ip.strip()
if src_group_name and src_group_group_id:
    raise Exception("Cannot specify both src group name and id")
if src_group_name and src_group_owner_id:
    raise Exception("Cannot specify both src group name and id")
if src_group_group_id and src_group_owner_id:
    raise Exception("Cannot specify both src group id and owner id")
if src_group_name:
    src_group_owner_id = self.ec2.get_all_security_groups(
        filters={'group_name': src_group_name})[0].owner_id
if src_group_group_id:
    src_group_owner_id = self.ec2.get_all_security_groups(
        filters={'group_id': src_group_group_id})[0].owner_id
if src_group_owner_id:
    src_group_name = self.ec2.get_all_security_groups(
        filters={'owner_id': src_group_owner_id,
                 'group_name': src_group_name})[0].name
if src_group_name:
    src_group_group_id = self.ec2.get_all_security_groups(
        filters={'owner_id': src_group_owner_id, 'group_name': src_group_name})[0].id
if src_group_owner_id:
    src_group_group_id = self.ec2.get_all_security_groups(
        filters={'owner_Id': src_group_owner_id, 'group_name': src_group_name})[0].id
if not (src_group_name or src_group_group_id or cidr_ip):
    raise Exception("Must specify either source security group, IP range, or both")
if not (from_port or to_port):
    raise Exception("Must specify either from or to port")
if from_port and to_port and from_port > to_port:
    raise Exception("From port must be <= to port")
if ip_protocol not in ["tcp", "udp", "icmp", "all"]:
    raise Exception("Invalid ip protocol")
if from_port and from_port < 0:
    raise Exception("Invalid from port")
if to_port and to_port < 0:
    raise Exception("Invalid to port")
if ip_protocol == "icmp":
    if from_port and from_port != -1:
        raise Exception("Icmp doesn't accept from port")
    if to_port and to_port != -1:
        raise Exception("Icmp doesn't accept to port")
if ip_protocol == "all":
    from_port = 0
    to_port = 65535
if from_port == 0 and to_port == 0:
    raise Exception("Invalid port range")
if cidr_ip:
    src_security_group_group_id = None
    src_security_owner_id = None
else:
    src_security_group_group_id = src_group_group_id
    src_security_owner_id = src_group_owner_id
if not self.ec2.authorize_security_group(
    group_id=self.id,
    ip_protocol=ip_protocol,
    from_port=from_port,
    to_port=to_port,
    cidr_ip=cidr_ip,
    src_security_group_group_id=src_security_group_group_id,
    src_security_group_owner_id=src_security_owner_id,
    src_security_group_name=src_group_name,
    dry_run=dry_run,
):
    raise Exception("Failed to add rule")

"""This function is used to determine which shell to use for the PShellCommand instance. If the user has specified a shell, it will use that shell if it is available, otherwise it will raise a ValueError with 'could not find a shell named "%s"' as the message. If the user has not specified a shell, it will use the first available preferred shell if that is specified, otherwise it will use the first available shell, with python as the least preferred shell. If no shell is available at all, it will use the default runner.

:param self: PShellCommand. An instance of the PShellCommand class.
:return: The selected shell to be used.
"""
shells = self.shells
preferred_shells = self.preferred_shells
if preferred_shells:
    for preferred_shell in preferred_shells:
        if preferred_shell in shells:
            return shells[preferred_shell]
    raise ValueError("could not find a shell named %s" % preferred_shell)
if self.shell:
    if self.shell in shells:
        return shells[self.shell]
    raise ValueError("could not find a shell named %s" % self.shell)
for shell in shells:
    if shell != "python":
        return shells[shell]
return shells["python"]

"""This function is to pluralize a string translation based on a singular/plural pair and a given number. It uses gettext plural forms support to handle different pluralization rules in different languages.

:param self: Localizer. An instance of the Localizer class.
:param singular: String. The singular form of the translation message.
:param plural: String. The plural form of the translation message.
:param n: Integer. The number that appears in the message, used for pluralization.
:param domain: String. The translation domain to use for pluralization. Defaults to None.
:param mapping: Dictionary. The interpolation mapping to be used on the result. Defaults to None.
:return: String. The pluralized translation message.
"""
if domain is None:
    domain = self.domain
if mapping is None:
    mapping = self.mapping
if self.pluralizer is None:
    return self.translate(singular if n == 1 else plural, domain=domain, mapping=mapping)
return self.translate(self.pluralizer(n, singular, plural), domain=domain, mapping=mapping)

