if unit_type not in self.possible_units:
    print("Unit type '" + unit_type + "' is invalid. Exiting command.")
    return

unit_name = self.command_tokens[2]
if not self.is_valid_regex(unit_name):
    print("Invalid regular expression for unit name.")
    return

if unit_type == "alias":
    self.unhide_alias(unit_name)
elif unit_type == "slot":
    self.unhide_slot(unit_name)
elif unit_type == "intent":
    self.unhide_intent(unit_name)
else:
    print("Invalid unit type '" + unit_type + "'. Exiting command.")

