"""This function takes a URL as input and parses it. It then convert the parsed result into a dictionary using the parsed result and unquote password which determines whether the password in the URL should be unquoted or not.

:param url: String. The URL to be parsed.
:param unquote_password: Bool. Whether to unquote the password in the URL. Defaults to False.
:return: Dictionary. The parsed URL as a dictionary.
"""
if not isinstance(url, str):
    raise TypeError("Invalid type for url, should be string.")
if not url.startswith("sqlcipher://"):
    raise ValueError("Invalid URL, must start with sqlcipher://")
url = url[11:]
pieces = url.split("?")
db_location = pieces[0]
if db_location == "":
    raise ValueError("Invalid URL, no database file specified.")
if unquote_password:
    password = unquote(urlparse.parse_qs(pieces[1])["password"][0])
else:
    password = urlparse.parse_qs(pieces[1])["password"][0]
kwargs = {}
if len(pieces) > 2:
    for item in pieces[2].split("&"):
        (name, value) = item.split("=")
        if name == "journal_mode":
            kwargs["journal_mode"] = value
        elif name == "foreign_keys":
            if value not in ["0", "1"]:
                raise ValueError("Invalid value for foreign_keys, must be 0 or 1.")
            kwargs["foreign_keys"] = bool(int(value))
        elif name == "synchronous":
            if value not in ["OFF", "NORMAL", "FULL", "EXTRA", "ASSERT", "TRUNCATE"]:
                raise ValueError("Invalid value for synchronous, must be one of: OFF, NORMAL, FULL, EXTRA, ASSERT, TRUNCATE.")
            kwargs["synchronous"] = value
        elif name == "cache_size":
            kwargs["cache_size"] = int(value)
        elif name == "page_size":
            kwargs["page_size"] = int(value)
        elif name == "mmap_size":
            kwargs["mmap_size"] = int(value)
        elif name == "temp_store":
            if value not in ["default", "file", "memory"]:
                raise ValueError("Invalid value for temp_store, must be one of: default, file, memory.")
            kwargs["temp_store"] = value
        elif name == "wal_mode":
            if value not in ["0", "1"]:
                raise ValueError("Invalid value for wal_mode, must be 0 or 1.")
            kwargs["wal_mode"] = bool(int(value))
        else:
            raise ValueError("Invalid URL parameter: %s" % name)
return {
    "database": db_location,
    "password": password,
    "journal_mode": kwargs.get("journal_mode"),
    "foreign_keys": kwargs.get("foreign_keys"),
    "synchronous": kwargs.get("synchronous"),
    "cache_size": kwargs.get("cache_size"),
    "page_size": kwargs.get("page_size"),
    "mmap_size": kwargs.get("mmap_size"),
    "temp_store": kwargs.get("temp_store"),
    "wal_mode": kwargs.get("wal_mode"),
}

"""Take a date or datetime instance as input and format it into a string that can be used in IMAP search criteria.


:param dt: Date or datetime, the date or datetime instance to be formatted.
:return: Bytes, the formatted date as a byte string.

"""
if dt.tzinfo is None:
    dt = dt.replace(tzinfo=UTC)
if dt.tzinfo != UTC:
    dt = dt.astimezone(UTC)
return to_bytes(dt.strftime("%d-%b-%Y"))

