"""This function creates a concrete instance of an IntentDefinition based on the given conditions. It first checks if all the necessary information is provided. If a variation is specified, it retrieves the definitions from the AST and checks if the identifier is already present. If it is, it returns the corresponding definition. Otherwise, it creates a new IntentDefinition instance with the provided identifier, modifiers representation, number of training examples, and number of testing examples.

:param self: IntentDefBuilder. An instance of the IntentDefBuilder class.
:return: IntentDefinition. The created concrete instance of IntentDefinition.
"""
if self._identifier is None:
    raise SyntaxError(
        "Tried to create an intent without specifying its identifier."
    )
if self._modifiers is None:
    raise SyntaxError(
        "Tried to create an intent without specifying its modifiers."
    )
if self._nb_training_ex is None:
    raise SyntaxError(
        "Tried to create an intent without specifying the number of training examples."
    )
if self._nb_testing_ex is None:
    raise SyntaxError(
        "Tried to create an intent without specifying the number of testing examples."
    )

if self._variation is None:
    return IntentDefinition(
        self._identifier,
        self._modifiers,
        self._nb_training_ex,
        self._nb_testing_ex,
    )

intent_definitions = AST.get_or_create().get_intent_definitions()
if self._variation in intent_definitions:
    return intent_definitions[self._variation]

return IntentDefinition(
    self._identifier,
    self._modifiers,
    self._nb_training_ex,
    self._nb_testing_ex,
    self._variation,
)

