"""This function clips the examples of a 2-dimensional array to given bounds. It checks if the input array is a numpy array, then it checks the bounds and clips the array accordingly. It first checks that the bounds are indeed tuple and that shape is an integer. If these conditions are not met, the function raises a error of type. It then extracts the lower and upper bounds, ensuring they are in the correct format and adjusting them to be arrays of the specified data type (dtype). The function enforces that the lower and upper bounds must be of the same shape and dimensionality, specifically either scalar or 1-dimensional arrays.

:param array: np.ndarray. The array to be clipped. After clipping, all examples have a 2-norm of at most `clip`.
:param bounds: tuple. The bounds of the form (min, max) which the array is to be clipped to. `min` and `max` must be scalar, unless the array is 2-dimensional.
:return: np.ndarray. The clipped array.
"""
if not isinstance(array, np.ndarray):
    raise TypeError(f"Array must be a numpy array, got {type(array)}.")

if not isinstance(bounds, tuple):
    raise TypeError(f"Bounds must be a tuple, got {type(bounds)}.")

if len(bounds) != 2:
    raise ValueError(f"Bounds must be of the form (min, max), got {bounds}.")

min_bound, max_bound = bounds

if not isinstance(min_bound, Real) or not isinstance(max_bound, Real):
    raise TypeError(f"Bounds must be scalar, got {min_bound} and {max_bound}.")

if array.ndim > 2:
    raise ValueError(f"Array must be 2-dimensional, got {array.ndim}.")

if array.ndim == 1:
    array = array.reshape(-1, 1)

if array.shape[1] > 1:
    raise ValueError(
        f"Array must be 2-dimensional, got {array.ndim} with shape {array.shape}."
    )

min_bound = np.array(min_bound, dtype=array.dtype)
max_bound = np.array(max_bound, dtype=array.dtype)

if min_bound.shape != max_bound.shape:
    raise ValueError(
        f"Bounds must have the same shape, got {min_bound.shape} and {max_bound.shape}."
    )

if min_bound.ndim > 1:
    raise ValueError(
        f"Bounds must be scalar or 1-dimensional, got {min_bound.ndim}."
    )

if min_bound.size != 1 and min_bound.size != array.shape[1]:
    raise ValueError(
        f"Bounds must have the same number of elements as the number of features, got {min_bound.size} and {array.shape[1]}."
    )

if min_bound.size == 1:
    min_bound = np.full(array.shape[1], min_bound.item(), dtype=array.dtype)

if max_bound.size == 1:
    max_bound = np.full(array.shape[1], max_bound.item(), dtype=array.dtype)

return np.clip(array, min_bound, max_bound)

